type Tone = "default" | "muted" | "info" | "success" | "warning" | "danger";

function toneColor(tone?: Tone): string {
  switch (tone) {
    case "danger":
      return "#f87171";
    case "warning":
      return "#fbbf24";
    case "success":
      return "#34d399";
    case "info":
      return "#60a5fa";
    case "muted":
      return "#94a3b8";
    default:
      return "#e2e8f0";
  }
}

export function Page(props: { children?: VChild[] }, ...children: VChild[]) {
  // Mirror web page shell: app bar on top, then side + main row, optional footer.
  const kids = [...(props.children ?? children)].filter(
    (child) => child !== null && child !== undefined && child !== false
  );
  const appBar = kids[0];
  const body = kids.slice(1);
  const footer =
    body.length > 0 && (body[body.length - 1] as any)?.props?.__silcSlot === "footer"
      ? body.pop()
      : undefined;
  return h(
    Box,
    { flexDirection: "column", width: "100%", height: "100%" },
    appBar,
    h(
      Box,
      { flexDirection: "row", width: "100%", flexGrow: 1, flexShrink: 1, gap: 1 },
      ...body
    ),
    footer
  );
}

