export function DataTable(props: {
  rows: Record<string, unknown>[];
  columns: string[];
  emptyText?: string;
  filterValue?: string;
  filterColumn?: string;
  filterAll?: string;
  sortable?: boolean;
  searchable?: boolean;
  selectable?: boolean;
  dense?: boolean;
  searchPlaceholder?: string;
  onSelect?: (row: Record<string, unknown>) => void;
}) {
  const rows = Array.isArray(props.rows) ? props.rows : [];
  const filtered =
    props.filterColumn && props.filterValue && props.filterValue !== (props.filterAll ?? "All")
      ? rows.filter((row) => String(row?.[props.filterColumn!] ?? "") === props.filterValue)
      : rows;
  if (!filtered.length) {
    return h(Text, { content: props.emptyText ?? "No records yet.", fg: "#94a3b8" });
  }
  const chunk = (text: string) => ({ __isChunk: true as const, text });
  const header = props.columns.map((column) => [chunk(column)]);
  const body = filtered.map((row) =>
    props.columns.map((column) => [chunk(String(row?.[column] ?? ""))])
  );
  return h(TextTableRenderable as any, {
    content: [header, ...body],
    showBorders: true,
    selectable: !!props.selectable || !!props.onSelect,
    width: "100%",
    height: Math.min(filtered.length + 3, props.dense ? 12 : 16),
    onSelectChange: props.onSelect
      ? (selection: { startRow?: number; endRow?: number } | number | null) => {
          let index = -1;
          if (typeof selection === "number") {
            index = selection;
          } else if (selection && typeof selection === "object") {
            index = typeof selection.startRow === "number" ? selection.startRow : -1;
          }
          // Header occupies row 0 in TextTableRenderable content.
          const dataIndex = index > 0 ? index - 1 : index;
          if (dataIndex >= 0 && dataIndex < filtered.length) {
            props.onSelect?.(filtered[dataIndex]!);
          }
        }
      : undefined,
  });
}

